#!/usr/bin/env python3
"""Radio PHY-policy models and an actual-C3 raw IRQ-ownership defect boot."""
import argparse,hashlib,json,re,shutil,subprocess
from pathlib import Path

def main():
 p=argparse.ArgumentParser();p.add_argument('--compiler',required=True,type=Path);p.add_argument('--qemu',required=True,type=Path);p.add_argument('--reference',required=True,type=Path);p.add_argument('--work',required=True,type=Path);a=p.parse_args();root=Path(__file__).resolve().parents[2];w=a.work.resolve();w.mkdir(parents=True,exist_ok=True);tree=w/'source';ref=a.reference.resolve();c=a.compiler.resolve();rows=[]
