 for name,module,before,after in defects:
  path=tree/'lib/platform'/module;original=path.read_text();assert before in original;path.write_text(original.replace(before,after));cmd=['nice','-n','19','python3',root/'tests/esp32/riscv-radio-platform-reference.py','--source-root',tree,'--compiler',c,'--reference',ref,'--work',w/name]
  try:r=subprocess.run(list(map(str,cmd)),cwd=root,capture_output=True,text=True,timeout=60)
  finally:path.write_text(original)
  log=r.stdout+r.stderr;(w/(name+'.log')).write_text(log);assert r.returncode!=0 and 'radio platform check ' in log,(name,log);rows.append(dict(defect=name,detected=True,CPU_execution=False,physical_hardware=False));print(name,'detected',flush=True)
 # Remove only the new raw-route preflight from an otherwise current adapter.
 path=tree/'lib/platform/esp32-riscv-radio-irq.flex';original=path.read_text();start=original.index('fn esp_radio_riscv_claimable(');end=original.index('\nfn esp_radio_cb_set_intr',start);old=original[start:end];path.write_text(original[:start]+'fn esp_radio_riscv_claimable(source,handler){return esp_radio_irq_can_claim(source,handler);}\n'+original[end:]);fixture=tree/'tests/esp32/riscv-radio-irq.flex';text=fixture.read_text();assert 'global ri_probe_set_intr=1;' in text;fixture.write_text(text.replace('global ri_probe_set_intr=1;','global ri_probe_set_intr=0;'));bad=w/'raw-IRQ-route'
 try:
  cmd=['nice','-n','19','python3',tree/'tests/esp32/riscv-osi-reference.py','--only-irq','--compiler',c,'--qemu',a.qemu,'--reference',ref,'--work',bad];r=subprocess.run(list(map(str,cmd)),cwd=tree,capture_output=True,text=True,timeout=60);(w/'raw-IRQ-route.log').write_text(r.stdout+r.stderr);assert r.returncode!=0 and '(1146048069, 15)' in r.stdout+r.stderr,(r.stdout,r.stderr)
  elf=bad/'c3-IRQ-linked.elf';line=next(x for x in subprocess.check_output(['llvm-nm','-P',str(elf)],text=True).splitlines() if x.startswith('ri_foreign_changed '));address=int(line.split()[2],16);cmd=['nice','-n','19','python3',root/'tests/esp32/riscv-rom-peer.py','--qemu',a.qemu,'--xip','--radio','--image',bad/'c3-IRQ.bin','--elf',elf,'--report',bad/'detected.json','--expected','15','--expect-memory',f'{address:#x}:1:7'];subprocess.run(list(map(str,cmd)),cwd=root,check=True,capture_output=True,timeout=30);rows.append(dict(defect='overwrite-enabled-raw-IRQ-route',detected=True,actual_C3_ROM=True,diagnostic_bits=7,bits=['raw route changed','callback published','CPU mask changed'],physical_hardware=False))
 finally:path.write_text(original);fixture.write_text(text)
 report=dict(pass_all=True,cases=rows,C3_deliberate_defect_boots=1,native_policy_defects=len(defects),C6_CPU_execution=False,physical_hardware=False,complete_radio_startup=False);(w/'report.json').write_text(json.dumps(report,indent=2)+'\n');print('PASS:',len(defects),'policy defects and1 actual C3 raw-route defect')
